// Emits site/tokens.css and site/tokens.js from packages/app/src/theme/tokens.ts
// so the marketing site and the app read the same numbers. Run:
//   node scripts/gen-site-tokens.mjs
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = dirname(dirname(fileURLToPath(import.meta.url)));
const mod = await import(join(root, 'packages/app/src/theme/tokens.ts'));
const vars = mod.cssVariables();

const css = [
  '/* GENERATED by scripts/gen-site-tokens.mjs from packages/app/src/theme/tokens.ts. Do not edit. */',
  ':root {',
  ...Object.entries(vars).map(([k, v]) => `  ${k}: ${v};`),
  '}',
  '',
].join('\n');
writeFileSync(join(root, 'site/tokens.css'), css);

const { canvasShadow, clipMix, ...rest } = mod.tokens;
const plain = JSON.parse(JSON.stringify({ ...rest, canvasShadow, clipMix }));
const js = [
  '// GENERATED by scripts/gen-site-tokens.mjs from packages/app/src/theme/tokens.ts. Do not edit.',
  `export const tokens = ${JSON.stringify(plain, null, 2)};`,
  'export const white = (a) => `rgba(255,255,255,${a})`;',
  'export const black = (a) => `rgba(0,0,0,${a})`;',
  'export const accentAlpha = (a) => `oklch(0.80 0.12 190 / ${a})`;',
  '',
].join('\n');
writeFileSync(join(root, 'site/tokens.js'), js);
console.log(`wrote ${Object.keys(vars).length} css vars`);
